                    # Move up
                    sandbox.apply_agent_force(0.0, 20.0)
                else:
                    # Move in y-direction to avoid wall (default to up)
                    sandbox.apply_agent_force(0.0, 20.0)
            else:
                # No wall in front, move forward
                sandbox.apply_agent_force(20.0, 0.0)
    else:
        # Post-unlock: move to exit zone
        if pos_x < 15.0:
            # Move right toward exit
            sandbox.apply_agent_force(20.0, 0.0)
        else:
            # Check if in exit zone
            if 0.5 <= pos_y <= 2.5:
                agent_action.exit_hold_count += 1
                if agent_action.exit_hold_count >= 5:
                    # Hold in exit zone
                    sandbox.apply_agent_force(0.0, 0.0)
            else:
                # Adjust vertical position
                if pos_y < 0.5:
                    sandbox.apply_agent_force(0.0, 20.0)
                elif pos_y > 2.5:
                    sandbox.apply_agent_force(0.0, -20.0)
